// Security presentation allowlist: read time is validated independently, never used as a wildcard for extra text.
function sourcesPageText(page:Element){
 const copy=page.cloneNode(true) as Element;const read=Array.from(copy.querySelectorAll("p")).find(node=>node.textContent?.startsWith("Read at "))!;expect(read.textContent).toMatch(/^Read at \d{1,2}\/\d{1,2}\/\d{4}, \d{1,2}:\d{2}:\d{2} [AP]M UTC\. This is a stored snapshot\.$/);read.textContent="Validated read timestamp";const walker=document.createTreeWalker(copy,NodeFilter.SHOW_TEXT);const chunks:string[]=[];let node:Node|null;while((node=walker.nextNode())!==null){const text=node.textContent?.replace(/\s+/g," ").trim();if(text)chunks.push(text);}return chunks.join(" ");
}
